	private bool Request00(string url, string data, ref string response, ref CookieContainer cookies, ref string error, string headers)
	{
		response = string.Empty;
		error = string.Empty;
		try
		{
			ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls | SecurityProtocolType.Tls11 | SecurityProtocolType.Tls12 | SecurityProtocolType.Tls13;
			ServicePointManager.ServerCertificateValidationCallback = IgnoreSSL;
			ServicePointManager.Expect100Continue = false;
			ServicePointManager.DefaultConnectionLimit = int.MaxValue;
			HttpWebRequest httpWebRequest = (HttpWebRequest)WebRequest.Create(url);
			if (cookies == null)
			{
				cookies = new CookieContainer();
			}
			httpWebRequest.CookieContainer = cookies;
			string userAgent = "okhttp/4.12.0";
			httpWebRequest.UserAgent = userAgent;
			string accept = "*/*";
			httpWebRequest.Accept = accept;
			string contentType = "application/json";
			httpWebRequest.ContentType = contentType;
			httpWebRequest.AllowAutoRedirect = false;
			httpWebRequest.KeepAlive = true;
			httpWebRequest.AutomaticDecompression = DecompressionMethods.GZip | DecompressionMethods.Deflate;
			httpWebRequest.Timeout = 55000;
			httpWebRequest.ReadWriteTimeout = 55000;
			if (!string.IsNullOrEmpty(headers))
			{
				string[] array = headers.Split('&');
				for (int i = 0; i < array.Length; i++)
				{
					string[] array2 = array[i].Split('#');
					if (array2.Length == 2)
					{
						httpWebRequest.Headers[array2[0]] = array2[1];
					}
				}
			}
			if (!string.IsNullOrEmpty(data))
			{
				string method = "POST";
				httpWebRequest.Method = method;
				using StreamWriter streamWriter = new StreamWriter(httpWebRequest.GetRequestStream());
				streamWriter.Write(data);
			}
			else
			{
				string method2 = "GET";
				httpWebRequest.Method = method2;
			}
			using (HttpWebResponse httpWebResponse = (HttpWebResponse)httpWebRequest.GetResponse())
			{
				using StreamReader streamReader = new StreamReader(httpWebResponse.GetResponseStream());
				response = streamReader.ReadToEnd();
			}
			return true;
		}
		catch (WebException ex)
		{
			if (ex.Response != null)
			{
				using StreamReader streamReader2 = new StreamReader(ex.Response.GetResponseStream());
				error = streamReader2.ReadToEnd();
			}
			else
			{
				error = ex.Message;
			}
			return false;
		}
	}

	public static byte[] FromBase32String(string encoded)
	{
		if (encoded == null)
		{
			throw new ArgumentNullException("encoded");
		}
		encoded = encoded.Trim().TrimEnd('=').ToUpper();
		if (encoded.Length == 0)
		{
			return new byte[0];
		}
		byte[] array = new byte[encoded.Length * 5 / 8];
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		string text = encoded;
		for (int i = 0; i < text.Length; i++)
		{
			char c = text[i];
			int num4 = CharToInt(c);
			if (num4 < 0)
			{
				throw new FormatException("Illegal character: `" + c + "`");
			}
			num = (num << 5) | (num4 & 0x1F);
			num3 += 5;
			if (num3 >= 8)
			{
				array[num2++] = (byte)(num >> num3 - 8);
				num3 -= 8;
			}
		}
		return array;
	}

	private static int CharToInt(char c)
	{
		return c switch
		{
			'2' => 26, 
			'3' => 27, 
			'4' => 28, 
			'5' => 29, 
			'6' => 30, 
			'7' => 31, 
			'A' => 0, 
			'B' => 1, 
			'C' => 2, 
			'D' => 3, 
			'E' => 4, 
			'F' => 5, 
			'G' => 6, 
			'H' => 7, 
			'I' => 8, 
			'J' => 9, 
			'K' => 10, 
			'L' => 11, 
			'M' => 12, 
